option.value:
spring.application.name=order-service server.port=8083 eureka.instance.prefer-ip-address=true
#Mongo spring.data.mongodb.uri=${SPRING_DATA_MONGODB_URI:mongodb://localhost:27017/database}
# Kafka Producer Configuration spring.kafka.bootstrap-servers=${KAFKA_BOOTSTRAP_SERVERS:localhost:9092,localhost:9094,localhost:9096}
#Eureka eureka.client.service-url.defaultZone=${EUREKA_SERVER_URL:http://localhost:8761/eureka/} eureka.client.register-with-eureka=true eureka.client.fetch-registry=true spring.security.user.name=eureka spring.security.user.password=password
# ======= Actuator + Prometheus ======= management.endpoints.web.exposure.include=* management.endpoint.health.show-details=always management.prometheus.metrics.export.enabled=true
# ======= Tracing (Zipkin + Spring Cloud Sleuth) ======= management.tracing.sampling.probability=1.0 management.zipkin.tracing.export.enabled=true management.zipkin.tracing.endpoint=${ZIPKIN_URL:http://localhost:9411/api/v2/spans}

